namespace
{
std::once_flag wireloom_type_plugins_once;
void wireloom_initialize_type_plugins()
{
    std::call_once(wireloom_type_plugins_once, []
    {
        // Stage 1: create all struct types without inheritance.
        // Create union shells in the same stage to support cross-type metadata references.
        ::CorpusEnumUnion::wireloom_Payload_type_context_instance().create_type();
        ::CorpusEnumUnion::wireloom_Choice_union_context_instance().create_type();

        // Stage 2: register metadata in dependency order after all shells exist.
        ::CorpusEnumUnion::wireloom_Payload_type_context_instance().add_members();
        ::CorpusEnumUnion::wireloom_Choice_union_context_instance().add_members();

        // Stage 3: create plugins only after every DynamicType is complete.
        ::CorpusEnumUnion::wireloom_Payload_type_context_instance().create_type_plugin();
        ::CorpusEnumUnion::wireloom_Choice_union_context_instance().create_type_plugin();
    });
}
} // namespace

